mapper.select:
SELECT `session_id` as sessionId, `code`, `expired_time` as expiredTime
FROM `login_captcha`
WHERE `session_id` = #{value}

SELECT `failed_count` as failedCount, `user_id` as userId, `last_failed_time` as lastFailedTime, `locked_until` as lockedUntil
FROM `login_failed_count`
WHERE `user_id` = #{value}

SELECT
    count(1)
FROM `login_audit` a

    JOIN `user` b ON b.`uuid` = a.`user_uuid`



        AND (
        b.`uuid` = #{keyword}
        OR b.`user_id` = #{keyword}
        OR b.`user_name` LIKE CONCAT(#{keyword}, '%')
        )


        AND a.`login_time` >= #{startTime}
        AND a.`login_time` <= #{endTime}

SELECT
    a.`id`,
    a.`user_uuid` AS userUuid,
    a.`ip`,
    a.`login_time` AS loginTime,
    a.`login_method` AS loginMethod
FROM `login_audit` a

    JOIN `user` b ON b.`uuid` = a.`user_uuid`



    AND (
        b.`uuid` = #{keyword}
        OR b.`user_id` = #{keyword}
        OR b.`user_name` LIKE CONCAT(#{keyword}, '%')
        OR a.`ip` LIKE CONCAT(#{keyword}, '%')
        OR a.`login_method` LIKE CONCAT(#{keyword}, '%')
    )


        AND a.`login_time` >= #{startTime}
        AND a.`login_time` <= #{endTime}


ORDER BY `id` DESC
LIMIT #{startNum}, #{pageSize}
